function draw(selected=step===1){ctx.clearRect(0,0,1600,650);ctx.save();pathPacket();ctx.shadowColor='#10203040';ctx.shadowBlur=32;ctx.shadowOffsetY=22;ctx.fillStyle=state.bg;ctx.fill();ctx.restore();ctx.save();pathPacket();ctx.clip();ctx.fillStyle=state.bg;ctx.fillRect(0,0,1600,650);let g=ctx.createLinearGradient(0,100,0,540);g.addColorStop(0,'#ffffffaa');g.addColorStop(.18,'#ffffff08');g.addColorStop(.42,'#ffffff38');g.addColorStop(.76,'#102e4920');g.addColorStop(.9,'#ffffff55');g.addColorStop(1,'#112d4940');ctx.fillStyle=g;ctx.fillRect(0,90,1600,470);for(const side of [55,1470])for(let i=0;i<80;i+=11){let crimp=ctx.createLinearGradient(side+i,0,side+i+11,0);crimp.addColorStop(0,'#ffffff55');crimp.addColorStop(.45,'#34506b36');crimp.addColorStop(1,'#ffffff66');ctx.fillStyle=crimp;ctx.fillRect(side+i,90,9,470);}for(const [x,flip] of [[155,1],[1445,-1]]){for(let j=0;j<3;j++){ctx.beginPath();ctx.moveTo(x,110+j*10);ctx.quadraticCurveTo(x+70*flip,200+j*30,x+110*flip,320);ctx.lineTo(x+40*flip,220);ctx.closePath();ctx.fillStyle=['#ffffff35','#14314d0e','#ffffff18'][j];ctx.fill();ctx.beginPath();ctx.moveTo(x,530-j*10);ctx.quadraticCurveTo(x+70*flip,440-j*30,x+110*flip,320);ctx.lineTo(x+40*flip,420);ctx.closePath();ctx.fill();}}
if(!state.removed){ctx.save();ctx.translate(state.x,state.y);ctx.rotate(state.rotation*Math.PI/180);let w=600*state.size/100,h=125*state.size/100;if(logoImg){h=w*logoImg.height/logoImg.width;if(h>270*state.size/100){w*=270*state.size/100/h;h=270*state.size/100;}if(state.recolor){const layer=document.createElement('canvas');layer.width=Math.ceil(w);layer.height=Math.ceil(h);const l=layer.getContext('2d');l.drawImage(logoImg,0,0,w,h);l.globalCompositeOperation='source-in';l.fillStyle=state.color;l.fillRect(0,0,w,h);ctx.drawImage(layer,-w/2,-h/2,w,h);}else ctx.drawImage(logoImg,-w/2,-h/2,w,h);}else{ctx.fillStyle=state.color;ctx.font=`900 ${90*state.size/100}px Arial`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('ÖRNEK KAFE',0,0);}if(selected){ctx.strokeStyle='#076bdb';ctx.lineWidth=2;ctx.setLineDash([9,8]);ctx.strokeRect(-w/2-15,-h/2-12,w+30,h+24);ctx.setLineDash([]);}ctx.restore();}ctx.save();ctx.fillStyle=state.textColor;ctx.font=`${state.font==='cursive'?'italic ':''}${state.textSize}px ${state.font}`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(state.text,state.tx,state.ty,1050);ctx.restore();ctx.restore();}
function refresh(){for(const [id,key] of [['size','size'],['rotation','rotation'],['text','text'],['font','font'],['textSize','textSize']])$(id).value=state[key];$('sizeValue').textContent='%'+state.size;$('rotationValue').textContent=state.rotation+'°';$('filename').textContent=state.removed?'Logo yok':state.logoName;$('bgName').textContent=palette.find(p=>p[0]===state.bg)?.[1]||'';$('undo').disabled=!history.length;$('recolorHint').textContent=state.recolor?'Tek renkli SVG / örnek logo: renk düzenleme etkin.':'Bu dosyada renk değiştirme kapalıdır. Renkli veya raster logonuzu istediğiniz renkte yükleyin.';document.querySelectorAll('[data-color-key]').forEach(b=>{b.classList.toggle('selected',state[b.dataset.colorKey]===b.dataset.color);b.disabled=b.dataset.colorKey==='color'&&!state.recolor;});draw();}
for(const [id,key,items] of [['backgrounds','bg',palette.slice(0,5)],['logoColors','color',palette],['textColors','textColor',palette.slice(0,5)]])for(const [color,name] of items){const b=document.createElement('button');b.style.background=color;b.title=name;b.setAttribute('aria-label',name);b.dataset.colorKey=key;b.dataset.color=color;b.onclick=()=>{remember();state[key]=color;refresh();};$(id).appendChild(b);}
for(const [id,key,numeric] of [['size','size',true],['rotation','rotation',true],['text','text',false],['font','font',false],['textSize','textSize',true]]){$(id).addEventListener('focus',()=>remember());$(id).oninput=()=>{state[key]=numeric?Number($(id).value):$(id).value;refresh();};}
$('upload').onchange=async e=>{const f=e.target.files[0];if(!f)return;const ticket=++loading;try{if(f.size>5*1024*1024)throw Error('Dosya en fazla 5 MB olmalı.');if(!/\.(png|jpe?g|svg)$/i.test(f.name))throw Error('Yalnızca PNG, JPG veya SVG yükleyin.');let data,recolor=false;if(/\.svg$/i.test(f.name)){({data,recolor}=svgSafe(await f.text()));}else{data=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(f);});if(!/^data:image\/(png|jpeg);/.test(data))throw Error('Dosya türü desteklenmiyor.');}const img=await loadImage(data);if(ticket!==loading)return;remember();state.logo=data;state.logoName=f.name;state.recolor=recolor;state.removed=false;state.rotation=0;logoImg=img;refresh();status('Logo cihazınızda yüklendi; sunucuya gönderilmedi.');}catch(err){status(err.message||'Dosya okunamadı.');}e.target.value='';};
$('remove').onclick=()=>{remember();state.removed=true;refresh();};$('addText').onclick=()=>{if(!state.text){remember();state.text='Yeni yazınız';refresh();}$('text').focus();$('text').select();};document.querySelectorAll('[data-align]').forEach(b=>b.onclick=()=>{remember();state.x={left:490,center:800,right:1110}[b.dataset.align];refresh();});
$('undo').onclick=async()=>{if(!history.length)return;const ticket=++loading,target=history.pop();const img=target.logo?await loadImage(target.logo):null;if(ticket!==loading)return;state=target;logoImg=img;refresh();status('Son düzenleme geri alındı.');};$('reset').onclick=()=>{remember();loading++;state={...initial};logoImg=null;refresh();status('Tasarım örnek başlangıç durumuna döndü.');};
let drag=null;canvas.onpointerdown=e=>{const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)*1600/r.width,y=(e.clientY-r.top)*650/r.height;const target=state.text&&Math.abs(y-state.ty)<70&&Math.abs(x-state.tx)<400?'text':'logo';if(target==='logo'&&state.removed)return;remember();drag={target,dx:x-(target==='text'?state.tx:state.x),dy:y-(target==='text'?state.ty:state.y)};canvas.setPointerCapture(e.pointerId);};canvas.onpointermove=e=>{if(!drag)return;const r=canvas.getBoundingClientRect(),x=Math.max(350,Math.min(1250,(e.clientX-r.left)*1600/r.width-drag.dx)),y=Math.max(215,Math.min(445,(e.clientY-r.top)*650/r.height-drag.dy));if(drag.target==='text'){state.tx=x;state.ty=y;}else{state.x=x;state.y=y;}draw();};canvas.onpointerup=canvas.onpointercancel=()=>drag=null;
