const districts={'İstanbul':['Kadıköy','Beşiktaş','Diğer ilçe'],'Muğla':['Bodrum','Menteşe','Marmaris','Fethiye','Diğer ilçe'],'Ankara':['Çankaya','Diğer ilçe'],'İzmir':['Konak','Diğer ilçe'],'Antalya':['Muratpaşa','Diğer ilçe'],'Diğer il':['Diğer ilçe']};function setDistrict(){const el=$('district');el.replaceChildren();for(const name of districts[$('province').value])el.add(new Option(name,name));calculate();}
function pricing(q,bg,province,district,cliche,inks){if(!Number.isInteger(inks)||inks<1||inks>6)throw Error('Örnek baskı rengi sayısı 1–6 arasında tam sayı olmalı.');if(!['new','existing'].includes(cliche))throw Error('Geçerli bir klişe durumu seçin.');if(!Number.isInteger(q)||q<1||q>1000000)throw Error('Adet 1–1.000.000 arasında tam sayı olmalı.');const boxes=Math.ceil(q/500),base=q*300,color=bg==='#ffffff'?0:q*40,plate=cliche==='existing'?0:inks*100000,shipping=province==='Muğla'&&district==='Bodrum'?0:boxes*20000,subtotal=base+color+plate+shipping,tax=Math.round(subtotal*.2);return {boxes,base,color,plate,shipping,subtotal,tax,total:subtotal+tax};}
const money=v=>(v/100).toLocaleString('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2})+' TL';let latest=null;
function calculate(){try{const q=Number($('qty').value),inks=Number($('inks').value);latest=pricing(q,state.bg,$('province').value,$('district').value,$('cliche').value,inks);$('boxes').textContent=`ⓘ Demo koli hesabı: 500 adet/koli → ${latest.boxes} koli`;$('review').disabled=false;const rows=[['Ürün bedeli',latest.base,`${q.toLocaleString('tr-TR')} × 3,00 TL`],['Renkli zemin farkı',latest.color,state.bg==='#ffffff'?'Beyaz zemin • fark yok':`${q.toLocaleString('tr-TR')} × 0,40 TL`],['Klişe bedeli',latest.plate,$('cliche').value==='existing'?'Mevcut onaylı klişe varsayımı • teknik kontrol gerekir':`${inks} renk × 1.000,00 TL`],['Kargo',latest.shipping,latest.shipping?`${latest.boxes} koli × 200,00 TL`:'Bodrum • HijyenLab teslimatı'],['Ara toplam',latest.subtotal,''],['Demo KDV (%20)',latest.tax,''],['Örnek genel toplam',latest.total,'']];$('breakdown').replaceChildren();for(const [label,value,note] of rows){const row=document.createElement('div');row.className='priceRow'+(label==='Örnek genel toplam'?' total':'');const l=document.createElement('span');l.textContent=label;if(note){const n=document.createElement('small');n.textContent=note;l.append(n);}const v=document.createElement('strong');v.textContent=money(value);row.append(l,v);$('breakdown').append(row);}status('');}catch(e){latest=null;$('review').disabled=true;$('breakdown').textContent=e.message;status(e.message);}}
$('province').onchange=setDistrict;for(const id of ['qty','district','cliche','inks'])$(id).oninput=calculate;
function go(n){if(n===3&&!latest){status('Önce geçerli bir adet seçin.');return;}step=n;['design','pricing','summary'].forEach((id,i)=>$(id).hidden=i+1!==n);document.querySelectorAll('[data-step]').forEach(b=>b.classList.toggle('active',Number(b.dataset.step)===n));if(n===2){$('mini').src=imageData();calculate();}if(n===3){$('finalImage').src=imageData();$('finalDetails').replaceChildren();for(const s of [`${$('qty').value} adet • ${$('province').value} / ${$('district').value}`,`Örnek genel toplam: ${money(latest.total)} (demo)`,`Klişe: ${$('cliche').selectedOptions[0].textContent} • ${$('inks').value} örnek baskı rengi`]){const p=document.createElement('p');p.textContent=s;$('finalDetails').append(p);}status('Gönderim yapılmadı. Bu yalnızca yerel demo özetidir.');}else status('');draw();window.scrollTo({top:0,behavior:'smooth'});}
$('next').onclick=()=>go(2);$('back').onclick=$('summaryBack').onclick=()=>go(1);$('review').onclick=()=>go(3);document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{calculate();go(Number(b.dataset.step));});setDistrict();refresh();go(1);
